/*
 * Rusty NPC Tracker — UI layer.
 *
 * Uses:
 *   window.RUSTY_NPC_DATA  (generated by build-data.mjs)
 *   window.RustyTracker    (tracker.js: parser, resolver, stats)
 *
 * Storage: IndexedDB ("rusty-npc-tracker" -> sessions / kv).
 * Live tailing: File System Access API (Chromium). Fallbacks: drag & drop, file picker, paste.
 */
(function () {
    'use strict';

    const T = window.RustyTracker;
    const DATA = window.RUSTY_NPC_DATA;
    if (!T || !DATA) {
        console.error('Rusty NPC Tracker: missing tracker.js or data/npc-data.js');
        return;
    }

    const indexes = T.buildIndexes(DATA);
    const RAT_NAMES_LC = indexes.rats.map((r) => r[1].toLowerCase());
    const $ = (id) => document.getElementById(id);

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------

    const SETTINGS_DEFAULTS = {
        essMode: 'auto',      // 'auto' | 'custom' | 'off'
        essCustom: 40,
        essNull: 40,
        taxPct: 0,
        incBank: false,
        useContext: true,
        essOverrides: {},
    };

    let settings = Object.assign({}, SETTINGS_DEFAULTS);
    let sessions = [];                    // session objects
    let sessionsById = Object.create(null);
    let activeViewId = 'all';             // 'all' or session id
    let currentView = null;               // { id, session, events, stats, all }

    let dirHandle = null;                 // FileSystemDirectoryHandle of the Gamelogs folder
    let watched = [];                     // [{ name, handle, offset, parser, sessionId }] newest first, max 3
    let pollTimer = null;
    let pollBusy = false;
    let userPaused = false;
    let lastLiveId = null;
    let followLiveSession = false;       // jump the view to the live session when the next one starts
    let suppressedFiles = Object.create(null); // files the user removed -> do not re-tail them

    let renderTimer = null;
    let saveTimer = null;
    let pendingSaves = Object.create(null);
    let allStatsDirty = true;
    let allStatsCache = null;
    let currentFeedRows = [];
    let currentNpcFixRefs = [];
    let currentSysFixRefs = [];
    let popover = null;
    let messageTimer = null;

    // Optional ESI location (read-only).
    let esiPollTimer = null;
    let esiPollBusy = false;
    let esiSystemId = null;
    let esiSystemName = null;
    let esiShipName = null;
    let esiShipTypeId = null;
    let esiOnline = null;
    let esiLastLogin = null;
    let esiLastLogout = null;
    let esiLoginCount = null;
    let esiNeedsRelink = false;
    let esiLastError = null;

    // Dashboard layout (order + collapsed state), persisted locally.
    const LAYOUT_KEY = 'rnpct_layout_v1';
    const layoutState = { order: {}, collapsed: {} };

    const sortState = {
        npc: { key: 'net', dir: -1 },
        sys: { key: 'net', dir: -1 },
        hist: { key: 'date', dir: -1 },
    };
    const NUMERIC_SORT = {
        npc: new Set(['qty', 'unit', 'gross', 'net', 'share', 'conf']),
        sys: new Set(['kills', 'gross', 'net', 'ess', 'bank', 'rate']),
        hist: new Set(['date', 'dur', 'kills', 'net', 'rate']),
    };

    // ------------------------------------------------------------------
    // DOM refs
    // ------------------------------------------------------------------

    const dom = {
        connectBtn: $('connectBtn'), reconnectBtn: $('reconnectBtn'), reconnectName: $('reconnectName'),
        pauseBtn: $('pauseBtn'), liveDot: $('liveDot'), connectStatus: $('connectStatus'),
        esiDot: $('esiDot'), esiLinkBtn: $('esiLinkBtn'), esiUnlinkBtn: $('esiUnlinkBtn'), esiStatus: $('esiStatus'),
        resetLayoutBtn: $('resetLayoutBtn'),
        fileInput: $('fileInput'), dropZone: $('dropZone'), pasteText: $('pasteText'), pasteBtn: $('pasteBtn'),
        essMode: $('essMode'), essCustom: $('essCustom'), essNull: $('essNull'),
        taxPct: $('taxPct'), incBank: $('incBank'), useContext: $('useContext'),
        sessionSelectRow: $('sessionSelectRow'), sessionSelect: $('sessionSelect'), sessionSelectMeta: $('sessionSelectMeta'),
        svNet: $('svNet'), ntNet: $('ntNet'), svKills: $('svKills'), ntKills: $('ntKills'),
        svDpsIn: $('svDpsIn'), ntDpsIn: $('ntDpsIn'), svDpsOut: $('svDpsOut'), ntDpsOut: $('ntDpsOut'),
        svRate: $('svRate'), ntRate: $('ntRate'), svTime: $('svTime'), ntTime: $('ntTime'),
        svGross: $('svGross'), ntGross: $('ntGross'), svBank: $('svBank'), ntBank: $('ntBank'),
        chartSvg: $('chartSvg'), chartTitle: $('chartTitle'),
        feedBody: $('feedBody'), feedCount: $('feedCount'), feedEmpty: $('feedEmpty'),
        npcTable: $('npcTable'), npcBody: $('npcBody'), npcCount: $('npcCount'), npcEmpty: $('npcEmpty'),
        sysTable: $('sysTable'), sysBody: $('sysBody'), sysCount: $('sysCount'), sysEmpty: $('sysEmpty'),
        btnImportRecent: $('btnImportRecent'), btnExportCsv: $('btnExportCsv'),
        btnExportJson: $('btnExportJson'), btnClearAll: $('btnClearAll'),
        atKills: $('atKills'), atNet: $('atNet'), atTime: $('atTime'), atSessions: $('atSessions'),
        histTable: $('histTable'), histBody: $('histBody'), histEmpty: $('histEmpty'),
        eveClock: $('eveClock'), messageArea: $('messageArea'),
    };

    // ------------------------------------------------------------------
    // Small utilities
    // ------------------------------------------------------------------

    function esc(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => (
            { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
        ));
    }

    function toast(msg, type, ms) {
        if (!dom.messageArea) return;
        dom.messageArea.textContent = msg;
        dom.messageArea.className = 'message-area' + (type ? ' ' + type : '');
        clearTimeout(messageTimer);
        messageTimer = setTimeout(() => { dom.messageArea.className = 'message-area hidden'; }, ms || 4500);
    }

    function setStatus(text) {
        if (dom.connectStatus) dom.connectStatus.textContent = text;
    }

    function pad2(n) { return (n < 10 ? '0' : '') + n; }

    function fmtDate(ms) {
        if (!ms) return '—';
        const d = new Date(ms);
        return d.getUTCFullYear() + '-' + pad2(d.getUTCMonth() + 1) + '-' + pad2(d.getUTCDate()) +
            ' ' + pad2(d.getUTCHours()) + ':' + pad2(d.getUTCMinutes());
    }

    function fmtISKcard(n) {
        if (n === null || n === undefined || isNaN(n)) return '—';
        if (Math.abs(n) >= 1e9) return (n / 1e9).toFixed(2) + ' B';
        return T.fmtISK(n);
    }

    function download(filename, text, mime) {
        const blob = new Blob([text], { type: mime || 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(() => URL.revokeObjectURL(url), 4000);
    }

    function csvField(v) {
        const s = String(v == null ? '' : v);
        return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
    }

    function lastEventT(s) {
        return s.events.length ? s.events[s.events.length - 1].t : 0;
    }

    function sessionSpanMs(s, now) {
        const start = s.start || (s.events.length ? s.events[0].t : 0);
        if (!start) return 0;
        const end = s.live ? now : Math.max(s.end || 0, s.logEnd || 0, lastEventT(s) || 0, start);
        return Math.max(0, end - start);
    }

    // ------------------------------------------------------------------
    // IndexedDB (tiny promise wrapper)
    // ------------------------------------------------------------------

    let dbPromise = null;

    function openDb() {
        if (dbPromise) return dbPromise;
        dbPromise = new Promise((resolve, reject) => {
            if (!window.indexedDB) { reject(new Error('IndexedDB unavailable')); return; }
            const req = indexedDB.open('rusty-npc-tracker', 1);
            req.onupgradeneeded = () => {
                const db = req.result;
                if (!db.objectStoreNames.contains('sessions')) db.createObjectStore('sessions', { keyPath: 'id' });
                if (!db.objectStoreNames.contains('kv')) db.createObjectStore('kv');
            };
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => reject(req.error);
        });
        return dbPromise;
    }

    function idbGetAll(storeName) {
        return openDb().then((db) => new Promise((resolve, reject) => {
            const tx = db.transaction(storeName, 'readonly');
            const req = tx.objectStore(storeName).getAll();
            req.onsuccess = () => resolve(req.result || []);
            req.onerror = () => reject(req.error);
        }));
    }

    function idbGet(storeName, key) {
        return openDb().then((db) => new Promise((resolve, reject) => {
            const tx = db.transaction(storeName, 'readonly');
            const req = tx.objectStore(storeName).get(key);
            req.onsuccess = () => resolve(req.result);
            req.onerror = () => reject(req.error);
        }));
    }

    function idbPut(storeName, value, key) {
        return openDb().then((db) => new Promise((resolve, reject) => {
            const tx = db.transaction(storeName, 'readwrite');
            const store = tx.objectStore(storeName);
            if (key === undefined) store.put(value); else store.put(value, key);
            tx.oncomplete = () => resolve(true);
            tx.onerror = () => reject(tx.error);
        }));
    }

    function idbDelete(storeName, key) {
        return openDb().then((db) => new Promise((resolve, reject) => {
            const tx = db.transaction(storeName, 'readwrite');
            tx.objectStore(storeName).delete(key);
            tx.oncomplete = () => resolve(true);
            tx.onerror = () => reject(tx.error);
        }));
    }

    function idbClear(storeName) {
        return openDb().then((db) => new Promise((resolve, reject) => {
            const tx = db.transaction(storeName, 'readwrite');
            tx.objectStore(storeName).clear();
            tx.oncomplete = () => resolve(true);
            tx.onerror = () => reject(tx.error);
        }));
    }

    // ------------------------------------------------------------------
    // Sessions
    // ------------------------------------------------------------------

    function invalidateAllStats() { allStatsDirty = true; }

    function createSession(id, file, char, start, source) {
        const s = {
            id: id,
            file: file,
            char: char || 'Unknown',
            start: start || null,
            end: 0,
            updated: Date.now(),
            source: source || 'file',
            live: false,
            events: [],
            damage: [],
            misses: [],
            logEnd: 0,
            amountOverrides: {},
            eventFixes: {},
        };
        sessions.push(s);
        sessionsById[id] = s;
        invalidateAllStats();
        return s;
    }

    function sortedSessions() {
        return sessions.slice().sort((a, b) => (b.start || b.updated || 0) - (a.start || a.updated || 0));
    }

    function sessionIdFor(char, name) { return (char || 'Unknown') + '|' + name; }

    function isWatchedSession(id) { return watched.some((w) => w.sessionId === id); }

    function saveSessionSoon(s) {
        pendingSaves[s.id] = s;
        clearTimeout(saveTimer);
        saveTimer = setTimeout(flushSaves, 1500);
    }

    function flushSaves() {
        const list = Object.keys(pendingSaves).map((k) => pendingSaves[k]);
        pendingSaves = Object.create(null);
        list.forEach((s) => { idbPut('sessions', s).catch((e) => console.warn('session save failed', e)); });
    }

    function suppressFile(name) {
        suppressedFiles[name] = true;
        idbPut('kv', suppressedFiles, 'suppressed').catch(() => {});
    }

    function unsuppressFile(name) {
        if (suppressedFiles[name]) {
            delete suppressedFiles[name];
            idbPut('kv', suppressedFiles, 'suppressed').catch(() => {});
        }
    }

    // ------------------------------------------------------------------
    // User corrections (NPC attribution overrides)
    // ------------------------------------------------------------------

    // Key identifying a kill for per-event fixes. Timestamps are second-precise;
    // same-amount kills within the same second are treated as one (usually the same NPC anyway).
    function fixKey(ev) { return ev.t + '|' + ev.a; }

    // Authoritative: rebuilds ev.override from the session's fix maps.
    function applyOverrides(s) {
        const fixes = s.eventFixes || {};
        const amts = s.amountOverrides || {};
        for (let i = 0; i < s.events.length; i++) {
            const ev = s.events[i];
            const fix = fixes[fixKey(ev)];
            const amt = amts[ev.a];
            if (fix != null) ev.override = fix;
            else if (amt != null) ev.override = amt;
            else if (ev.override !== undefined) delete ev.override;
        }
    }

    function assignNpc(session, ev, typeId, applyAll) {
        if (!session || !ev) return;
        session.eventFixes = session.eventFixes || {};
        session.eventFixes[fixKey(ev)] = typeId;
        if (applyAll) {
            session.amountOverrides = session.amountOverrides || {};
            session.amountOverrides[ev.a] = typeId;
        }
        applyOverrides(session);
        saveSessionSoon(session);
        invalidateAllStats();
        scheduleRender(true);
        const idx = indexes.ratById.get(typeId);
        const name = idx != null ? indexes.rats[idx][1] : 'NPC';
        toast('Assigned ' + name + (applyAll
            ? ' to all ' + T.fmtISK(ev.a) + ' ISK kills in this session'
            : ' to this kill'), 'success', 3000);
    }

    function resetEventFix(session, ev) {
        if (!session) return;
        if (session.eventFixes) delete session.eventFixes[fixKey(ev)];
        applyOverrides(session);
        saveSessionSoon(session);
        invalidateAllStats();
        scheduleRender(true);
        toast('Reset this kill to automatic matching', '', 2500);
    }

    function resetAmountFix(session, amount) {
        if (!session) return;
        if (session.amountOverrides) delete session.amountOverrides[amount];
        applyOverrides(session);
        saveSessionSoon(session);
        invalidateAllStats();
        scheduleRender(true);
        toast('Removed the session-wide fix for ' + T.fmtISK(amount) + ' ISK kills', '', 2500);
    }

    // ------------------------------------------------------------------
    // Text ingestion (file drop / picker / paste)
    // ------------------------------------------------------------------

    function ingestText(name, text, source) {
        const parser = new T.LogParser();
        const res = parser.feed(text);
        const char = parser.char || 'Unknown';
        const id = source === 'paste'
            ? ('paste|' + char + '|' + (parser.sessionStart || (res.events[0] && res.events[0].t) || Date.now()))
            : sessionIdFor(char, name);
        if (source === 'file') unsuppressFile(name);
        let s = sessionsById[id];
        if (!s) s = createSession(id, name, char, parser.sessionStart, source);
        s.file = name;
        s.char = char;
        if (parser.sessionStart) s.start = parser.sessionStart;
        s.events = res.events;
        s.damage = res.damage || [];
        s.misses = res.misses || [];
        s.logEnd = res.lastTs || (parser.lastTs || 0);
        s.source = source;
        s.live = isWatchedSession(id);
        s.end = lastEventT(s) || s.start || 0;
        s.updated = Date.now();
        applyOverrides(s);
        saveSessionSoon(s);
        invalidateAllStats();
        return id;
    }

    async function handleFiles(fileList) {
        const files = Array.from(fileList || []);
        if (!files.length) return;
        setStatus('Analysing ' + files.length + ' log file(s)…');
        let imported = 0;
        let kills = 0;
        let lastId = null;
        for (const f of files) {
            try {
                const id = ingestText(f.name, await f.text(), 'file');
                lastId = id;
                imported++;
                kills += sessionsById[id].events.length;
            } catch (err) {
                console.warn('failed to import', f.name, err);
            }
        }
        if (imported === 1 && lastId) { activeViewId = lastId; selectSig = ''; }
        scheduleRender(true);
        toast('Imported ' + imported + ' log file(s) — ' + kills + ' kill lines', 'success');
        if (dirHandle) updateTailStatus(); else setStatus('Imported ' + imported + ' file(s). Connect the Gamelogs folder for live tracking.');
    }

    function handlePaste() {
        const text = dom.pasteText.value;
        if (!text || text.length < 20) { toast('Paste some log text first', 'error'); return; }
        const id = ingestText('pasted log', text, 'paste');
        dom.pasteText.value = '';
        activeViewId = id;
        selectSig = '';
        scheduleRender(true);
        toast('Parsed ' + sessionsById[id].events.length + ' kill lines from pasted text', 'success');
    }

    // ------------------------------------------------------------------
    // Live tailing (File System Access API)
    // ------------------------------------------------------------------

    function fsSupported() { return typeof window.showDirectoryPicker === 'function'; }

    // EVE writes game logs to Documents\EVE\logs\Gamelogs by default. The picker opens at
    // Documents; wherever the user picks, we locate the actual Gamelogs folder ourselves.
    const LOG_NAME_RE = /^\d{8}_\d{6}_.*\.txt$/i;

    async function dirHasLogs(dir) {
        try {
            for await (const e of dir.values()) {
                if (e.kind === 'file' && LOG_NAME_RE.test(e.name)) return true;
            }
        } catch (err) { /* unreadable */ }
        return false;
    }

    async function findGamelogsBelow(root, maxDepth) {
        const queue = [{ dir: root, parts: [], depth: 0 }];
        let visited = 0;
        while (queue.length && visited < 300) {
            const cur = queue.shift();
            visited++;
            if (cur.depth >= maxDepth) continue;
            try {
                for await (const e of cur.dir.values()) {
                    if (e.kind !== 'directory') continue;
                    const parts = cur.parts.concat(e.name);
                    if (/^gamelogs$/i.test(e.name)) return { handle: e, parts: parts };
                    queue.push({ dir: e, parts: parts, depth: cur.depth + 1 });
                }
            } catch (err) { /* skip unreadable folders */ }
        }
        return null;
    }

    /**
     * From a picked folder, find the EVE Gamelogs directory:
     * the folder itself, a known relative path (EVE\logs\Gamelogs), or a bounded search.
     * Returns { handle, found, fromDirect, label }.
     */
    async function resolveGamelogsDir(root) {
        if (/^gamelogs$/i.test(root.name) || await dirHasLogs(root)) {
            return { handle: root, found: true, fromDirect: true, label: root.name };
        }
        const known = [['EVE', 'logs', 'Gamelogs'], ['logs', 'Gamelogs'], ['Gamelogs']];
        for (const parts of known) {
            try {
                let cur = root;
                for (const part of parts) cur = await cur.getDirectoryHandle(part);
                if (/^gamelogs$/i.test(cur.name) || await dirHasLogs(cur)) {
                    return { handle: cur, found: true, fromDirect: false, label: root.name + '\\' + parts.join('\\') };
                }
            } catch (err) { /* keep probing */ }
        }
        const hit = await findGamelogsBelow(root, 3);
        if (hit) {
            return { handle: hit.handle, found: true, fromDirect: false, label: root.name + '\\' + hit.parts.join('\\') };
        }
        return { handle: root, found: false, fromDirect: false, label: root.name };
    }

    async function connectFolder() {
        if (!fsSupported()) {
            dom.fileInput.click();
            toast('This browser cannot auto-follow logs — pick or drag the game log file instead. For live tracking use Chrome or Edge.', 'error', 6500);
            return;
        }
        let picked;
        try {
            picked = await window.showDirectoryPicker({ id: 'eve-gamelogs', mode: 'read', startIn: 'documents' });
        } catch (err) {
            return; // cancelled
        }
        setStatus('Looking for EVE game logs below "' + picked.name + '"…');
        const resolved = await resolveGamelogsDir(picked);
        if (!resolved.found) {
            setStatus('No EVE logs found in "' + picked.name + '" — click "Connect EVE logs" and pick Documents (recommended) or your Gamelogs folder.');
            toast('No EVE logs found in "' + picked.name + '". Try again and pick the Documents folder — the tracker finds EVE\\logs\\Gamelogs by itself.', 'error', 9000);
            return;
        }
        dirHandle = resolved.handle;
        try { await idbPut('kv', dirHandle, 'gamelogsDir'); } catch (err) { /* non-fatal */ }
        hideReconnect();
        dom.connectBtn.classList.add('hidden');
        dom.pauseBtn.classList.remove('hidden');
        userPaused = false;
        followLiveSession = true;
        if (resolved.fromDirect) {
            setStatus('Connected to "' + dirHandle.name + '" — scanning for logs…');
        } else {
            toast('Found EVE logs at ' + resolved.label, 'success', 5000);
            setStatus('Connected — ' + resolved.label);
        }
        await startWatching();
    }

    async function startWatching() {
        if (!dirHandle) return;
        startPolling();
        updateLiveUI();
        await pollOnce();
    }

    function startPolling() {
        if (pollTimer || userPaused || !dirHandle) return;
        pollTimer = setInterval(() => { pollOnce(); }, 2000);
        updateLiveUI();
    }

    function stopPolling() {
        if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
        updateLiveUI();
    }

    function setUserPaused(paused) {
        userPaused = paused;
        if (paused) {
            stopPolling();
            setStatus('Paused — EVE keeps logging, click Resume to catch up.');
        } else if (dirHandle) {
            startPolling();
            pollOnce();
        }
        updateLiveUI();
    }

    async function listLogs() {
        const out = [];
        if (!dirHandle) return out;
        for await (const entry of dirHandle.values()) {
            if (entry.kind === 'file' && /\.txt$/i.test(entry.name)) out.push({ name: entry.name, handle: entry });
        }
        out.sort((a, b) => (a.name < b.name ? 1 : a.name > b.name ? -1 : 0));
        return out;
    }

    async function pollOnce() {
        if (!dirHandle || pollBusy || userPaused) return;
        pollBusy = true;
        try {
            const logs = await listLogs();
            if (!logs.length) {
                setStatus('Connected to "' + dirHandle.name + '" — no .txt logs found. Start EVE with logging enabled.');
                return;
            }
            const targets = [logs[0]];
            watched.forEach((w) => {
                if (targets.length < 3 && !targets.some((t) => t.name === w.name)) targets.push({ name: w.name, handle: w.handle });
            });
            const next = [];
            for (const t of targets) {
                if (suppressedFiles[t.name]) continue;
                let w = watched.find((x) => x.name === t.name);
                if (!w) {
                    w = await startLiveSession(t.name, t.handle);
                } else {
                    w = (await readAppended(w)) || w;
                }
                if (w) next.push(w);
            }
            const prevIds = new Set(watched.map((w) => w.sessionId));
            watched = next;
            const currIds = new Set(watched.map((w) => w.sessionId));
            prevIds.forEach((id) => {
                if (!currIds.has(id)) {
                    const s = sessionsById[id];
                    if (s && s.live) {
                        s.live = false;
                        s.end = lastEventT(s) || s.end;
                        saveSessionSoon(s);
                        invalidateAllStats();
                    }
                }
            });
            updateTailStatus();
        } catch (err) {
            console.warn('log poll failed', err);
            setStatus('Log read error: ' + (err && err.message ? err.message : err));
        } finally {
            pollBusy = false;
            updateLiveUI();
        }
    }

    function updateTailStatus() {
        if (!dirHandle || userPaused) return;
        if (!watched.length) {
            setStatus('Connected to "' + dirHandle.name + '" — waiting for a game log…');
            return;
        }
        const newest = watched[0];
        const s = sessionsById[newest.sessionId];
        setStatus('Live — tailing ' + watched.length + ' log file' + (watched.length > 1 ? 's' : '') +
            (s && s.char ? ' · ' + s.char : '') + ' · ' + newest.name);
    }

    async function startLiveSession(name, handle) {
        const file = await handle.getFile();
        const parser = new T.LogParser();
        const res = parser.feed(await file.text());
        const char = parser.char || 'Unknown';
        const id = sessionIdFor(char, name);
        let s = sessionsById[id];
        if (!s) s = createSession(id, name, char, parser.sessionStart, 'live');
        s.file = name;
        s.char = char;
        if (parser.sessionStart) s.start = parser.sessionStart;
        s.events = res.events;
        s.damage = res.damage || [];
        s.misses = res.misses || [];
        s.logEnd = res.lastTs || (parser.lastTs || 0);
        s.source = 'live';
        s.live = true;
        s.end = lastEventT(s) || s.start || 0;
        s.updated = Date.now();
        applyOverrides(s);
        applyEsiFallback(s);
        saveSessionSoon(s);
        invalidateAllStats();
        if (followLiveSession || activeViewId === 'all' || activeViewId === lastLiveId) activeViewId = id;
        followLiveSession = false;
        lastLiveId = id;
        scheduleRender();
        return { name: name, handle: handle, offset: file.size, parser: parser, sessionId: id };
    }

    async function readAppended(w) {
        const file = await w.handle.getFile();
        if (file.size < w.offset) {
            return await startLiveSession(w.name, w.handle); // log was replaced/truncated: full reparse
        }
        if (file.size === w.offset) return null;
        const text = await file.slice(w.offset).text();
        w.offset = file.size;
        const res = w.parser.feed(text);
        const s = sessionsById[w.sessionId];
        if (!s) return w;
        let added = 0;
        for (const ev of res.events) { s.events.push(ev); added++; }
        if (!Array.isArray(s.damage)) s.damage = [];
        if (!Array.isArray(s.misses)) s.misses = [];
        for (const d of (res.damage || [])) { s.damage.push(d); added++; }
        for (const m of (res.misses || [])) { s.misses.push(m); added++; }
        if (res.lastTs && res.lastTs > (s.logEnd || 0)) s.logEnd = res.lastTs;
        const esiFilled = added ? applyEsiToEvents(res.events) : 0;
        if (added || res.jumps.length || esiFilled) {
            s.end = lastEventT(s) || s.end;
            s.updated = Date.now();
            applyOverrides(s);
            saveSessionSoon(s);
            invalidateAllStats();
            updateTailStatus();
            scheduleRender();
        }
        return w;
    }

    async function importRecentLogs() {
        if (!dirHandle) { toast('Connect the Gamelogs folder first (or drag files in).', 'error'); return; }
        const logs = await listLogs();
        const take = logs.slice(0, 10).filter((l) => !watched.some((w) => w.name === l.name));
        if (!take.length) { toast('Nothing new to import — the newest logs are already being tracked.', '', 3500); return; }
        setStatus('Importing ' + take.length + ' recent log(s)…');
        let kills = 0;
        for (const l of take) {
            try {
                const f = await l.handle.getFile();
                const id = ingestText(l.name, await f.text(), 'file');
                kills += sessionsById[id].events.length;
            } catch (err) {
                console.warn('import failed', l.name, err);
            }
        }
        scheduleRender(true);
        toast('Imported ' + take.length + ' recent log(s) — ' + kills + ' kill lines', 'success');
        updateTailStatus();
    }

    function showReconnect(name) {
        if (!dom.reconnectBtn) return;
        dom.reconnectName.textContent = name;
        dom.reconnectBtn.classList.remove('hidden');
    }

    function hideReconnect() {
        if (dom.reconnectBtn) dom.reconnectBtn.classList.add('hidden');
    }

    function updateLiveUI() {
        if (dom.liveDot) {
            dom.liveDot.className = 'live-dot' + (pollTimer ? ' on' : (dirHandle && userPaused ? ' paused' : ''));
        }
        if (dom.pauseBtn) {
            dom.pauseBtn.classList.toggle('hidden', !dirHandle);
            dom.pauseBtn.innerHTML = userPaused ? '<i class="fas fa-play"></i> Resume' : '<i class="fas fa-pause"></i> Pause';
        }
    }

    // ------------------------------------------------------------------
    // Optional ESI location (read-only)
    // ------------------------------------------------------------------

    function esiModule() { return window.RNPC_ESI || null; }
    function esiConfigured() { const m = esiModule(); return !!(m && m.configured); }
    function esiCharacter() {
        const m = esiModule();
        return m && m.configured ? m.character() : null;
    }

    function updateEsiUI() {
        const configured = esiConfigured();
        const char = esiCharacter();
        if (dom.esiLinkBtn) dom.esiLinkBtn.classList.toggle('hidden', !configured || !!char);
        if (dom.esiUnlinkBtn) dom.esiUnlinkBtn.classList.toggle('hidden', !char);
        if (dom.esiDot) {
            let dot = 'esi-dot';
            if (esiLastError) dot += ' err';
            else if (char && esiOnline === false) dot += ' off';
            else if (char) dot += ' on';
            dom.esiDot.className = dot;
        }
        if (!dom.esiStatus) return;

        if (!configured) {
            dom.esiStatus.textContent = 'Optional ESI status is not configured yet.';
            dom.esiStatus.title = '';
            return;
        }
        if (!char) {
            dom.esiStatus.textContent = 'Optional: link a character for read-only location, current ship and online status.';
            dom.esiStatus.title = '';
            return;
        }

        const bits = ['Linked as <b>' + esc(char.name) + '</b>'];
        if (esiSystemName) bits.push('System: <b>' + esc(esiSystemName) + '</b>');
        if (esiShipName) bits.push('Ship: <b>' + esc(esiShipName) + '</b>');
        if (esiOnline === true) bits.push('<b>Online</b>');
        else if (esiOnline === false) bits.push('Offline');
        if (esiNeedsRelink) bits.push('<span class="warn">re-link to enable ship/online</span>');
        if (esiLastError) bits.push('<span class="err">' + esc(esiLastError) + '</span>');
        dom.esiStatus.innerHTML = bits.join(' · ') + ' — fills systems only when the log has no jump/undock line.';

        const detail = [];
        if (esiShipTypeId) detail.push('Ship type ID: ' + esiShipTypeId);
        if (esiLastLogin) detail.push('Last login: ' + T.fmtDateTime(Date.parse(esiLastLogin)));
        if (esiLastLogout) detail.push('Last logout: ' + T.fmtDateTime(Date.parse(esiLastLogout)));
        if (esiLoginCount != null) detail.push('Total logins: ' + esiLoginCount);
        dom.esiStatus.title = detail.join('\n');
    }

    async function linkEsi() {
        const m = esiModule();
        if (!m || !m.configured) { toast('The ESI app is not configured yet.', 'error'); return; }
        try {
            await m.login();
        } catch (err) {
            toast(err && err.message ? err.message : 'Could not start EVE login', 'error', 6000);
        }
    }

    function unlinkEsi() {
        const m = esiModule();
        if (m) m.logout();
        stopEsiPolling();
        esiSystemId = null;
        esiSystemName = null;
        esiShipName = null;
        esiShipTypeId = null;
        esiOnline = null;
        esiLastLogin = null;
        esiLastLogout = null;
        esiLoginCount = null;
        esiNeedsRelink = false;
        esiLastError = null;
        updateEsiUI();
        toast('EVE character unlinked', '', 2500);
    }

    function esiSystemNameFor(id) {
        const info = indexes.systemsById ? indexes.systemsById.get(Number(id)) : null;
        return info ? info.name : null;
    }

    function esiErrorText(reason) {
        return (reason && reason.message) ? reason.message : 'ESI request failed';
    }
    function esiIsForbidden(reason) { return /HTTP 403/i.test(esiErrorText(reason)); }
    function esiIsAuthError(text) { return /session expired|not signed in|HTTP 401/i.test(text); }

    async function pollEsiStatus() {
        if (esiPollBusy || !esiConfigured() || !esiCharacter() || document.hidden) return;
        esiPollBusy = true;
        try {
            const m = esiModule();
            const call = (name) => (typeof m[name] === 'function')
                ? m[name]()
                : Promise.reject(new Error(name + ' is not available — refresh the page'));
            const [locR, shipR, onlineR] = await Promise.allSettled([
                call('getLocation'), call('getShip'), call('getOnline'),
            ]);

            const errors = [];
            let authExpired = false;

            if (locR.status === 'fulfilled' && locR.value && locR.value.solar_system_id != null) {
                esiSystemId = Number(locR.value.solar_system_id);
                esiSystemName = esiSystemNameFor(locR.value.solar_system_id) || ('System ' + locR.value.solar_system_id);
            } else {
                const msg = locR.status === 'rejected' ? esiErrorText(locR.reason) : 'ESI did not return a solar system';
                errors.push('location: ' + msg);
                if (esiIsAuthError(msg)) authExpired = true;
            }

            if (shipR.status === 'fulfilled' && shipR.value) {
                esiShipName = shipR.value.ship_name || (shipR.value.ship_type_id ? 'Ship ' + shipR.value.ship_type_id : null);
                esiShipTypeId = shipR.value.ship_type_id || null;
            } else {
                const msg = shipR.status === 'rejected' ? esiErrorText(shipR.reason) : 'no ship data';
                if (esiIsForbidden(shipR.reason)) esiNeedsRelink = true;
                else errors.push('ship: ' + msg);
                if (esiIsAuthError(msg)) authExpired = true;
            }

            if (onlineR.status === 'fulfilled' && onlineR.value) {
                esiOnline = !!onlineR.value.online;
                esiLastLogin = onlineR.value.last_login || null;
                esiLastLogout = onlineR.value.last_logout || null;
                esiLoginCount = (onlineR.value.logins != null) ? onlineR.value.logins : null;
            } else {
                const msg = onlineR.status === 'rejected' ? esiErrorText(onlineR.reason) : 'no online data';
                if (esiIsForbidden(onlineR.reason)) esiNeedsRelink = true;
                else errors.push('online: ' + msg);
                if (esiIsAuthError(msg)) authExpired = true;
            }

            if (shipR.status === 'fulfilled' && onlineR.status === 'fulfilled') esiNeedsRelink = false;
            esiLastError = errors.length ? errors.join('; ') : null;

            if (authExpired) {
                const mod = esiModule();
                if (mod) mod.logout();
                stopEsiPolling();
                esiSystemName = null;
                esiShipName = null;
                esiShipTypeId = null;
                esiOnline = null;
                esiNeedsRelink = false;
            }

            updateEsiUI();

            if (!authExpired) {
                let touched = false;
                watched.forEach((w) => {
                    const s = sessionsById[w.sessionId];
                    if (s && applyEsiFallback(s)) touched = true;
                });
                if (touched) { invalidateAllStats(); scheduleRender(true); }
            }
        } finally {
            esiPollBusy = false;
        }
    }

    function startEsiPolling() {
        if (esiPollTimer || !esiConfigured() || !esiCharacter()) return;
        pollEsiStatus();
        esiPollTimer = setInterval(pollEsiStatus, 10000);
        updateEsiUI();
    }

    function stopEsiPolling() {
        if (esiPollTimer) { clearInterval(esiPollTimer); esiPollTimer = null; }
        updateEsiUI();
    }

    /**
     * Stamp a batch of newly appended events with the current ESI system.
     * Used for live events only; historical imports keep their log-derived data.
     */
    function applyEsiToEvents(events) {
        if (!esiSystemName) return 0;
        let changed = 0;
        for (const ev of events) {
            if (!ev.sys) { ev.sys = esiSystemName; changed++; }
        }
        return changed;
    }

    /**
     * Only guess when the log gave us no system at all. If the log contains any
     * jump/undock system, those lines are authoritative; null gaps stay manual.
     */
    function applyEsiFallback(session) {
        if (!session || !session.live || !esiSystemName) return false;
        if (!session.events.length || session.events.some((ev) => !!ev.sys)) return false;
        const changed = applyEsiToEvents(session.events);
        if (changed) saveSessionSoon(session);
        return changed > 0;
    }

    // ------------------------------------------------------------------
    // Dashboard layout: collapse + drag-to-reorder
    // ------------------------------------------------------------------

    function layoutId(el) { return el ? (el.getAttribute('data-layout-id') || '') : ''; }
    function layoutParentKey(parent) { return (parent && parent.id) ? parent.id : ''; }

    function loadLayout() {
        try {
            const raw = localStorage.getItem(LAYOUT_KEY);
            if (!raw) return;
            const parsed = JSON.parse(raw);
            if (parsed && typeof parsed === 'object') {
                layoutState.order = (parsed.order && typeof parsed.order === 'object') ? parsed.order : {};
                layoutState.collapsed = (parsed.collapsed && typeof parsed.collapsed === 'object') ? parsed.collapsed : {};
            }
        } catch (e) { /* ignore corrupted layout */ }
    }

    function saveLayout() {
        try { localStorage.setItem(LAYOUT_KEY, JSON.stringify(layoutState)); } catch (e) { /* private mode */ }
    }

    function layoutHeaderFor(el) {
        if (el.classList.contains('summary-card')) return el.querySelector('.summary-header');
        const children = Array.from(el.children);
        for (const child of children) {
            if (child.tagName === 'H3' || child.classList.contains('table-title')) return child;
        }
        return null;
    }

    function wrapLayoutBody(el, header) {
        if (Array.from(el.children).some((c) => c.classList.contains('layout-body'))) return;
        const body = document.createElement('div');
        body.className = 'layout-body';
        Array.from(el.children).forEach((child) => {
            if (child !== header) body.appendChild(child);
        });
        el.appendChild(body);
    }

    function addLayoutTools(el, header) {
        if (header.querySelector('.layout-tools')) return;
        const tools = document.createElement('span');
        tools.className = 'layout-tools';

        const grip = document.createElement('button');
        grip.type = 'button';
        grip.className = 'layout-btn layout-grip';
        grip.title = 'Drag to move';
        grip.setAttribute('aria-label', 'Move');
        grip.innerHTML = '<i class="fas fa-grip-vertical"></i>';

        const collapse = document.createElement('button');
        collapse.type = 'button';
        collapse.className = 'layout-btn layout-collapse';
        collapse.title = 'Minimise';
        collapse.setAttribute('aria-label', 'Minimise');
        collapse.innerHTML = '<i class="fas fa-chevron-up"></i>';

        tools.appendChild(grip);
        tools.appendChild(collapse);
        header.appendChild(tools);

        grip.addEventListener('pointerdown', (e) => startLayoutDrag(e, el));
        collapse.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            toggleLayoutCollapse(el);
        });
    }

    function setLayoutCollapsed(el, collapsed) {
        el.classList.toggle('layout-collapsed', !!collapsed);
        const btn = el.querySelector('.layout-collapse');
        if (btn) {
            btn.innerHTML = collapsed
                ? '<i class="fas fa-chevron-down"></i>'
                : '<i class="fas fa-chevron-up"></i>';
            btn.title = collapsed ? 'Expand' : 'Minimise';
            btn.setAttribute('aria-label', collapsed ? 'Expand' : 'Minimise');
        }
    }

    function toggleLayoutCollapse(el) {
        const collapsed = !el.classList.contains('layout-collapsed');
        setLayoutCollapsed(el, collapsed);
        const id = layoutId(el);
        if (id) {
            layoutState.collapsed[id] = collapsed;
            saveLayout();
        }
    }

    function saveLayoutOrder(parent) {
        const key = layoutParentKey(parent);
        if (!key) return;
        layoutState.order[key] = Array.from(parent.children)
            .filter((c) => c.hasAttribute('data-layout-id'))
            .map((c) => c.getAttribute('data-layout-id'));
        saveLayout();
    }

    function reorderLayout(parent, savedIds) {
        const children = Array.from(parent.children);
        const items = children.filter((c) => c.hasAttribute('data-layout-id'));
        if (!items.length) return;
        const map = new Map(items.map((el) => [el.getAttribute('data-layout-id'), el]));
        const ordered = [];
        (savedIds || []).forEach((id) => {
            const el = map.get(id);
            if (el && ordered.indexOf(el) === -1) ordered.push(el);
        });
        items.forEach((el) => { if (ordered.indexOf(el) === -1) ordered.push(el); });

        const layoutSet = new Set(items);
        const result = children.map((c) => (layoutSet.has(c) ? null : c));
        let next = 0;
        for (let i = 0; i < result.length; i++) {
            if (result[i] === null) result[i] = ordered[next++];
        }
        if (result.some((c) => !c)) return;
        parent.append(...result);
    }

    function applySavedLayout() {
        const parents = new Set();
        document.querySelectorAll('[data-layout-id]').forEach((el) => {
            if (el.parentElement) parents.add(el.parentElement);
        });
        parents.forEach((parent) => {
            const key = layoutParentKey(parent);
            const saved = key ? layoutState.order[key] : null;
            if (Array.isArray(saved) && saved.length) reorderLayout(parent, saved);
        });
    }

    function setupLayout() {
        const items = Array.from(document.querySelectorAll('[data-layout-id]'));
        items.forEach((el) => {
            if (el.getAttribute('data-layout-built') === '1') return;
            el.setAttribute('data-layout-built', '1');
            el.classList.add('layout-item');
            const header = layoutHeaderFor(el);
            if (!header) return;
            addLayoutTools(el, header);
            wrapLayoutBody(el, header);
            setLayoutCollapsed(el, !!(layoutId(el) && layoutState.collapsed[layoutId(el)]));
        });
        applySavedLayout();
    }

    function startLayoutDrag(e, el) {
        if (!el || !el.parentElement) return;
        if (document.body.classList.contains('layout-drag-active')) return;
        if (e.pointerType === 'mouse' && e.button !== 0) return;
        e.preventDefault();
        e.stopPropagation();

        const parent = el.parentElement;
        const rect = el.getBoundingClientRect();
        const placeholder = document.createElement('div');
        placeholder.className = 'layout-placeholder';
        placeholder.style.width = rect.width + 'px';
        placeholder.style.height = rect.height + 'px';
        parent.insertBefore(placeholder, el);

        const prevStyle = {};
        ['position', 'left', 'top', 'width', 'height', 'margin', 'zIndex',
            'pointerEvents', 'boxSizing', 'transition'].forEach((key) => {
            prevStyle[key] = el.style[key];
        });

        el.classList.add('layout-dragging');
        el.style.position = 'fixed';
        el.style.left = rect.left + 'px';
        el.style.top = rect.top + 'px';
        el.style.width = rect.width + 'px';
        el.style.height = rect.height + 'px';
        el.style.margin = '0';
        el.style.zIndex = '9999';
        el.style.pointerEvents = 'none';
        el.style.boxSizing = 'border-box';
        el.style.transition = 'none';
        document.body.classList.add('layout-drag-active');

        const offsetX = e.clientX - rect.left;
        const offsetY = e.clientY - rect.top;
        const isGrid = parent.classList.contains('summary-grid');
        const siblings = () => Array.from(parent.children).filter((c) => (
            c !== el && c !== placeholder && c.hasAttribute('data-layout-id')
        ));

        const move = (ev) => {
            if (ev.cancelable) ev.preventDefault();
            el.style.left = (ev.clientX - offsetX) + 'px';
            el.style.top = (ev.clientY - offsetY) + 'px';

            const sibs = siblings();
            let placed = false;
            if (isGrid) {
                let best = null;
                let bestDist = Infinity;
                for (const sib of sibs) {
                    const r = sib.getBoundingClientRect();
                    const dx = ev.clientX - (r.left + r.width / 2);
                    const dy = ev.clientY - (r.top + r.height / 2);
                    const dist = dx * dx + dy * dy;
                    if (dist < bestDist) { bestDist = dist; best = { sib, r }; }
                }
                if (best) {
                    const r = best.r;
                    let before;
                    if (ev.clientY < r.top + r.height / 2) before = true;
                    else if (ev.clientY > r.top + r.height / 2) before = false;
                    else before = ev.clientX < r.left + r.width / 2;
                    parent.insertBefore(placeholder, before ? best.sib : best.sib.nextSibling);
                    placed = true;
                }
            } else {
                for (const sib of sibs) {
                    const r = sib.getBoundingClientRect();
                    if (ev.clientY < r.top + r.height / 2) {
                        parent.insertBefore(placeholder, sib);
                        placed = true;
                        break;
                    }
                }
                if (!placed && sibs.length) {
                    parent.insertBefore(placeholder, sibs[sibs.length - 1].nextSibling);
                    placed = true;
                }
            }
            if (!placed) parent.appendChild(placeholder);

            if (ev.clientY < 70) window.scrollBy(0, -14);
            else if (ev.clientY > window.innerHeight - 70) window.scrollBy(0, 14);
        };

        const end = () => {
            document.removeEventListener('pointermove', move);
            document.removeEventListener('pointerup', end);
            document.removeEventListener('pointercancel', end);
            document.body.classList.remove('layout-drag-active');
            el.classList.remove('layout-dragging');
            Object.keys(prevStyle).forEach((key) => { el.style[key] = prevStyle[key]; });
            if (placeholder.parentNode) placeholder.replaceWith(el);
            else parent.appendChild(el);
            saveLayoutOrder(parent);
        };

        document.addEventListener('pointermove', move, { passive: false });
        document.addEventListener('pointerup', end);
        document.addEventListener('pointercancel', end);
    }

    // ------------------------------------------------------------------
    // Stats
    // ------------------------------------------------------------------

    function trackerEss() {
        return {
            enabled: settings.essMode !== 'off',
            customRate: settings.essMode === 'custom' ? Number(settings.essCustom) : null,
            nullsecRate: Number(settings.essNull),
            overrides: settings.essOverrides || {},
            includesBank: !!settings.incBank,
            taxPct: Number(settings.taxPct),
            useContext: !!settings.useContext,
        };
    }

    function essSignature() {
        return [settings.essMode, settings.essCustom, settings.essNull, settings.taxPct,
            settings.incBank ? 1 : 0, settings.useContext ? 1 : 0,
            JSON.stringify(settings.essOverrides || {})].join('~');
    }

    // Cached per-session stats (used by the history table; ~10s bucket for live sessions)
    function sessionStats(s) {
        const key = s.events.length + '|' + (s.logEnd || 0) + '|' + (s.end || 0) + '|' + (s.live ? Math.floor(Date.now() / 10000) : 0) + '|' + essSignature();
        if (s._stats && s._statsKey === key) return s._stats;
        s._stats = T.computeStats(s, indexes, trackerEss(), Date.now());
        s._statsKey = key;
        return s._stats;
    }

    function computeAllStats() {
        if (!allStatsDirty && allStatsCache) return allStatsCache;
        const now = Date.now();
        const events = [];
        const damage = [];
        const misses = [];
        const eventSession = new Map();
        let spanMs = 0;
        let tickNet = 0, tickGross = 0, completedTicks = 0;
        for (const s of sessions) {
            for (const ev of s.events) { events.push(ev); eventSession.set(ev, s); }
            for (const d of (s.damage || [])) damage.push(d);
            for (const m of (s.misses || [])) misses.push(m);
            spanMs += sessionSpanMs(s, now);
            const ss = sessionStats(s);
            tickNet += ss.tickNet || 0;
            tickGross += ss.tickGross || 0;
            completedTicks += ss.completedTicks || 0;
        }
        const st = T.computeStats({ events: events, start: null, live: false }, indexes, trackerEss(), now);
        st.spanMs = spanMs;
        st.completedTicks = completedTicks;
        st.tickNet = tickNet;
        st.tickGross = tickGross;
        st.avgTickNet = completedTicks ? tickNet / completedTicks : null;
        st.iskPerHour = completedTicks ? (tickNet / completedTicks) * 3 : null;
        st.grossPerHour = completedTicks ? (tickGross / completedTicks) * 3 : null;
        st.last3Ticks = 0;
        st.last3Net = 0;
        st.last3PerHour = null;
        st.currentTick = null;
        st._events = events;
        st._damage = damage;
        st._misses = misses;
        st._eventSession = eventSession;
        allStatsCache = st;
        allStatsDirty = false;
        return st;
    }

    function getActiveView() {
        if (activeViewId === 'all' || !sessionsById[activeViewId]) {
            activeViewId = 'all';
            const st = computeAllStats();
            return { id: 'all', session: null, events: st._events, stats: st, all: true };
        }
        const s = sessionsById[activeViewId];
        return { id: s.id, session: s, events: s.events, stats: T.computeStats(s, indexes, trackerEss(), Date.now()), all: false };
    }

    function scheduleRender(immediate) {
        if (immediate) {
            if (renderTimer) { clearTimeout(renderTimer); renderTimer = null; }
            renderAll();
            return;
        }
        if (renderTimer) return;
        renderTimer = setTimeout(() => { renderTimer = null; renderAll(); }, 250);
    }

    // ------------------------------------------------------------------
    // Rendering
    // ------------------------------------------------------------------

    let selectSig = '';

    function renderAll() {
        currentView = getActiveView();
        renderSessionSelect();
        renderSummary(currentView);
        renderChart(currentView.stats);
        renderFeed(currentView);
        renderNpcTable(currentView);
        renderSysTable(currentView);
        renderHistory();
        renderAllTime();
    }

    function renderSessionSelect() {
        if (!dom.sessionSelectRow) return;
        if (!sessions.length) { dom.sessionSelectRow.classList.add('hidden'); return; }
        dom.sessionSelectRow.classList.remove('hidden');
        const ordered = sortedSessions();
        const sig = ordered.map((s) => s.id + ':' + s.events.length + ':' + (s.live ? 1 : 0)).join('|') + '#' + activeViewId;
        if (sig !== selectSig) {
            selectSig = sig;
            dom.sessionSelect.innerHTML =
                '<option value="all">All sessions (' + sessions.length + ')</option>' +
                ordered.map((s) => '<option value="' + esc(s.id) + '">' +
                    esc(fmtDate(s.start || s.updated) + ' · ' + s.char + ' · ' + s.events.length + ' kills' + (s.live ? ' · LIVE' : '') + ' · ' + s.file) +
                    '</option>').join('');
            dom.sessionSelect.value = sessionsById[activeViewId] ? activeViewId : 'all';
        }
        if (dom.sessionSelectMeta) {
            const s = sessionsById[activeViewId];
            dom.sessionSelectMeta.textContent = s
                ? (s.file + (s.live ? ' · tailing live' : '') + ' · ' + s.events.length + ' kills')
                : ('All ' + sessions.length + ' sessions · ' + (currentView ? currentView.stats.kills : 0) + ' kills');
        }
    }

    function renderSummary(view) {
        const st = view.stats;
        const ess = st.essSettings || trackerEss();
        const dps = view.all
            ? T.computeDps({ damage: st._damage || [], misses: st._misses || [], start: null, live: false }, Date.now(), st.spanMs)
            : T.computeDps(view.session, Date.now());
        const live = !!(view.session && view.session.live);
        if (dom.svNet) dom.svNet.textContent = fmtISKcard(st.net);
        if (dom.ntNet) dom.ntNet.textContent = netNote(st, ess);
        if (dom.svKills) dom.svKills.textContent = st.kills.toLocaleString('en-US');
        if (dom.ntKills) dom.ntKills.textContent = killsNote(st);
        if (dom.svDpsIn) dom.svDpsIn.textContent = fmtDps(live ? dps.live.inDps : dps.peak.inDps);
        if (dom.ntDpsIn) dom.ntDpsIn.textContent = dpsNote('in', dps, live);
        if (dom.svDpsOut) dom.svDpsOut.textContent = fmtDps(live ? dps.live.outDps : dps.peak.outDps);
        if (dom.ntDpsOut) dom.ntDpsOut.textContent = dpsNote('out', dps, live);
        if (dom.svRate) dom.svRate.textContent = st.iskPerHour != null ? fmtISKcard(st.iskPerHour) : '—';
        if (dom.ntRate) dom.ntRate.textContent = rateNote(st, live);
        if (dom.svTime) dom.svTime.textContent = T.fmtDuration(st.spanMs);
        if (dom.ntTime) dom.ntTime.textContent = st.start
            ? ('started ' + T.fmtClock(st.start) + ' EVE' + (view.session && view.session.live ? ' · live' : ''))
            : '';
        if (dom.svGross) dom.svGross.textContent = fmtISKcard(st.gross);
        if (dom.ntGross) dom.ntGross.textContent = 'exact ' + T.fmtISK(st.gross) + ' ISK from the logs';
        if (dom.svBank) dom.svBank.textContent = fmtISKcard(st.bank);
        if (dom.ntBank) dom.ntBank.textContent = bankNote(st, ess);
    }

    function fmtDps(n) {
        if (n == null || isNaN(n)) return '—';
        return Math.round(n).toLocaleString('en-US');
    }

    function dpsNote(dir, dps, live) {
        const isIn = dir === 'in';
        const total = isIn ? dps.totals.in : dps.totals.out;
        if (!total) return 'no ' + (isIn ? 'incoming' : 'outgoing') + ' damage lines in this view';
        const avg60 = isIn ? dps.avg60.inDps : dps.avg60.outDps;
        const avg = isIn ? dps.avg.inDps : dps.avg.outDps;
        const peak = isIn ? dps.peak.inDps : dps.peak.outDps;
        const rate = isIn ? dps.hitRate.inPct : dps.hitRate.outPct;
        const parts = [];
        if (live) {
            parts.push('live 10s');
            parts.push('60s avg ' + fmtDps(avg60));
            parts.push('peak ' + fmtDps(peak));
        } else {
            parts.push('peak 10s');
            parts.push('active avg ' + fmtDps(avg));
        }
        parts.push('total ' + T.fmtInt(total));
        if (rate != null) parts.push('hit ' + Math.round(rate) + '%');
        return parts.join(' · ');
    }

    function netNote(st, ess) {
        if (!ess.enabled) return 'ESS ignored — gross equals net';
        const parts = [];
        if (ess.customRate != null) parts.push('after custom ' + ess.customRate + '% ESS');
        else parts.push('after ESS (nullsec bank ' + ess.nullsecRate + '%)');
        if (ess.taxPct) parts.push('corp tax ' + ess.taxPct + '%');
        parts.push(ess.includesBank ? 'incl. bank payout' : 'excl. bank payout');
        return parts.join(' · ');
    }

    function rateNote(st, live) {
        const tickMin = st.tickMs ? Math.round(st.tickMs / 60000) : 20;
        if (!st.completedTicks) {
            const bits = ['waiting for first full ' + tickMin + '-min tick'];
            if (st.currentTick) {
                bits.push((live ? 'current ' : 'partial tick ') + T.fmtISK(st.currentTick.net, true) + ' ISK');
                if (live) bits.push(T.fmtDuration(st.currentTick.remainingMs) + ' left');
                else bits.push('not counted');
            }
            return bits.join(' · ');
        }
        const avg = st.tickNet / st.completedTicks;
        const bits = [
            tickMin + 'm ticks · 3/hr',
            st.completedTicks + ' full tick' + (st.completedTicks === 1 ? '' : 's'),
            'avg ' + T.fmtISK(avg, true) + '/tick',
        ];
        if (st.completedTicks >= 3 && st.last3PerHour != null) {
            bits.push('last 3 ticks: ' + T.fmtISK(st.last3PerHour, true) + '/h');
        }
        if (st.currentTick) {
            bits.push((live ? 'current ' : 'partial tick ') + T.fmtISK(st.currentTick.net, true) +
                (live ? ' · ' + T.fmtDuration(st.currentTick.remainingMs) + ' left' : ' · not counted'));
        }
        return bits.join(' · ');
    }

    function bankNote(st, ess) {
        if (!ess.enabled) return 'ESS handling is off';
        if (!st.bank) return 'no ESS systems in this view';
        return 'held by the ESS main bank — pays out if not stolen';
    }

    function killsNote(st) {
        const bits = [];
        const resolvedOnly = Math.max(0, st.resolved - st.manual);
        if (resolvedOnly) bits.push(resolvedOnly + ' resolved');
        if (st.manual) bits.push(st.manual + ' manual');
        if (st.guessed) bits.push(st.guessed + ' guessed');
        if (st.unknown) bits.push(st.unknown + ' unmatched');
        return bits.join(' · ');
    }

    function fmtSecVal(sec) {
        return (sec >= 0 ? sec.toFixed(1) : '-' + Math.abs(sec).toFixed(1));
    }

    function shortName(n) {
        return n.length > 22 ? n.slice(0, 21) + '…' : n;
    }

    function renderChart(st) {
        if (!dom.chartSvg) return;
        const pts = st.timeline || [];
        if (pts.length < 2) {
            dom.chartSvg.innerHTML = '<text x="150" y="50" fill="#7d8999" font-size="10" text-anchor="middle">Not enough data yet</text>';
            if (dom.chartTitle) dom.chartTitle.textContent = '';
            return;
        }
        const t0 = pts[0].t;
        const t1 = pts[pts.length - 1].t;
        const max = pts[pts.length - 1].cum || 1;
        const W = 300, H = 90, pad = 3;
        const coords = pts.map((p) => {
            const x = t1 > t0 ? ((p.t - t0) / (t1 - t0)) * W : 0;
            const y = H - pad - Math.max(0, p.cum / max) * (H - pad * 2);
            return x.toFixed(1) + ',' + y.toFixed(1);
        });
        const line = coords.join(' ');
        const area = '0,' + (H - pad) + ' ' + line + ' ' + W + ',' + (H - pad);
        dom.chartSvg.innerHTML =
            '<polygon points="' + area + '" fill="rgba(255,140,61,0.12)"></polygon>' +
            '<polyline points="' + line + '" fill="none" stroke="#ff8c3d" stroke-width="1.5" vector-effect="non-scaling-stroke"></polyline>';
        if (dom.chartTitle) {
            dom.chartTitle.textContent = T.fmtClock(t0) + ' → ' + T.fmtClock(t1) + ' EVE · ' +
                (st.iskPerHour != null ? T.fmtISK(st.iskPerHour, true) + ' ISK/hr' : '');
        }
    }

    // ---------------------- Live feed ----------------------

    function feedRowHtml(i, ev) {
        const res = T.resolveEvent(ev, indexes, { useContext: !!settings.useContext });
        const fid = ' data-feed-i="' + i + '"';
        let status;
        if (res.status === 'm') status = '<span class="chip info">manual</span>';
        else if (res.status === 'r') status = '<span class="chip ok">resolved</span>';
        else if (res.status === 'g') status = '<span class="chip warn">guess</span>';
        else status = '<span class="chip err">unmatched</span>';
        if (ev.adj) status += ' <span class="chip adj" title="The game adjusted this payout (ESS / bounty risk modifier)">adj</span>';
        if (res.idx != null && res.mult && res.mult !== 1) status += ' <span class="chip">×' + res.mult + '</span>';

        const isResolved = (res.status === 'r' || res.status === 'm');
        let actions = '<button class="mini-btn assign" ' + fid + ' title="' +
            (isResolved ? 'Change the NPC for this kill' : 'Assign the NPC for this kill') + '">' +
            (isResolved ? '<i class="fas fa-pen"></i>' : 'Assign') + '</button>';
        if (res.status === 'g' && res.candidates && res.candidates.length > 1) {
            const names = new Set([indexes.rats[res.candidates[0]][1]]);
            const picks = [];
            for (let k = 1; k < res.candidates.length && picks.length < 3; k++) {
                const ix = res.candidates[k];
                const nm = indexes.rats[ix][1];
                if (names.has(nm)) continue;
                names.add(nm);
                picks.push(ix);
            }
            const alt = picks.map((ix) =>
                '<button class="mini-btn" ' + fid + ' data-assign-idx="' + ix + '" title="Assign ' +
                esc(indexes.rats[ix][1]) + '">' + esc(shortName(indexes.rats[ix][1])) + '</button>'
            ).join(' ');
            if (alt) actions = alt + ' ' + actions;
        }
        return '<tr>' +
            '<td class="mono" style="color:var(--text-muted);">' + T.fmtClock(ev.t) + '</td>' +
            '<td>' + npcCellHtml(res, ev) + '</td>' +
            '<td>' + systemCellHtml(ev.sys) + '</td>' +
            '<td class="num">' + T.fmtISK(ev.a) + '</td>' +
            '<td>' + status + ' ' + actions + '</td>' +
            '</tr>';
    }

    function npcCellHtml(res, ev) {
        if (res.idx != null) {
            const rat = indexes.rats[res.idx];
            const sub = T.ratGroup(indexes, res.idx) || T.ratFaction(indexes, res.idx);
            return '<div class="npc-cell">' +
                '<img class="npc-icon" src="https://images.evetech.net/types/' + rat[0] + '/icon?size=32" alt="" loading="lazy" onerror="this.classList.add(\'hidden\')">' +
                '<div class="npc-meta"><span class="name">' + esc(rat[1]) + (res.status === 'g' ? '?' : '') + '</span>' +
                '<span class="sub">' + esc(sub) + '</span></div></div>';
        }
        return '<div class="npc-cell">' +
            '<span class="npc-icon-fallback"><i class="fas fa-question"></i></span>' +
            '<div class="npc-meta"><span class="name">Unidentified</span>' +
            '<span class="sub">no NPC matches ' + T.fmtISK(ev.a) + ' ISK — assign it</span></div></div>';
    }

    function systemCellHtml(sysName) {
        if (!sysName) return '<span style="color:var(--text-muted);">Unknown</span>';
        const info = indexes.systems.get(sysName.toLowerCase());
        return '<div class="system-cell">' +
            (info ? '<span class="sec-pill ' + T.secClass(info.sec) + '">' + fmtSecVal(info.sec) + '</span>' : '') +
            esc(sysName) + '</div>';
    }

    function renderFeed(view) {
        if (!dom.feedBody) return;
        const events = view.events;
        const recent = events.slice().sort((a, b) => b.t - a.t).slice(0, 60);
        currentFeedRows = [];
        let html = '';
        for (const ev of recent) {
            const session = view.session || (view.stats._eventSession ? view.stats._eventSession.get(ev) : null);
            currentFeedRows.push({ session: session, ev: ev });
            html += feedRowHtml(currentFeedRows.length - 1, ev);
        }
        dom.feedBody.innerHTML = html;
        if (dom.feedEmpty) dom.feedEmpty.classList.toggle('hidden', recent.length > 0);
        if (dom.feedCount) {
            dom.feedCount.textContent = recent.length
                ? ('· latest ' + recent.length + ' of ' + events.length.toLocaleString('en-US') + ' · times EVE/UTC')
                : '';
        }
    }

    // ---------------------- By NPC ----------------------

    function findSampleEvent(view, n) {
        const wantGuess = (n.idx != null && n.conf.g > 0);
        for (const ev of view.events) {
            const r = T.resolveEvent(ev, indexes, { useContext: !!settings.useContext });
            if (n.idx == null) {
                if (r.status === 'u' && ev.a === n.amount) return ev;
            } else if (r.idx === n.idx && (!wantGuess || r.status === 'g')) {
                return ev;
            }
        }
        return null;
    }

    function npcRowHtml(n, totalNet) {
        const isUnres = n.idx == null;
        const rat = isUnres ? null : indexes.rats[n.idx];
        const sub = isUnres ? '' : (T.ratGroup(indexes, n.idx) || '');
        const parts = [];
        if (n.conf.m) parts.push('<span class="chip info">' + n.conf.m + ' manual</span>');
        if (n.conf.r) parts.push('<span class="chip ok">' + n.conf.r + ' resolved</span>');
        if (n.conf.g) parts.push('<span class="chip warn">' + n.conf.g + ' guess</span>');
        if (n.conf.u) parts.push('<span class="chip err">' + n.conf.u + ' unmatched</span>');
        let fixBtn = '';
        if (isUnres || n.conf.u || n.conf.g) {
            currentNpcFixRefs.push(n);
            fixBtn = ' <button class="mini-btn assign" data-npc-fix="' + (currentNpcFixRefs.length - 1) + '">Fix</button>';
        }
        const share = totalNet > 0 ? (100 * n.net / totalNet) : 0;
        return '<tr>' +
            '<td><div class="npc-cell">' +
            (rat
                ? '<img class="npc-icon" src="https://images.evetech.net/types/' + rat[0] + '/icon?size=32" alt="" loading="lazy" onerror="this.classList.add(\'hidden\')">'
                : '<span class="npc-icon-fallback"><i class="fas fa-question"></i></span>') +
            '<div class="npc-meta"><span class="name">' + esc(rat ? rat[1] : 'Unresolved ' + T.fmtISK(n.amount) + ' ISK') + '</span>' +
            (sub ? '<span class="sub">' + esc(sub) + '</span>' : '') + '</div></div></td>' +
            '<td>' + (isUnres ? '<span class="chip err">unknown</span>' : esc(T.ratFaction(indexes, n.idx))) + '</td>' +
            '<td class="num">' + n.qty + '</td>' +
            '<td class="num">' + T.fmtISK(rat ? Math.round(rat[2]) : n.amount) + '</td>' +
            '<td class="num">' + T.fmtISK(n.gross) + '</td>' +
            '<td class="num">' + T.fmtISK(n.net) + '</td>' +
            '<td class="num">' + share.toFixed(1) + '%</td>' +
            '<td>' + parts.join(' ') + fixBtn + '</td>' +
            '</tr>';
    }

    function renderNpcTable(view) {
        if (!dom.npcBody) return;
        const st = view.stats;
        const totalNet = st.net || 1;
        currentNpcFixRefs = [];
        const rows = st.byNpc.map((n) => {
            const isUnres = n.idx == null;
            const confWeight = n.conf.m ? 3 : (n.conf.g ? 1 : (n.conf.r ? 2 : 0));
            return {
                name: (isUnres ? 'unresolved ' + n.amount : indexes.rats[n.idx][1]).toLowerCase(),
                faction: isUnres ? '' : T.ratFaction(indexes, n.idx),
                qty: n.qty,
                unit: isUnres ? n.amount : Math.round(indexes.rats[n.idx][2]),
                gross: n.gross,
                net: n.net,
                share: n.net,
                conf: confWeight,
                html: npcRowHtml(n, totalNet),
            };
        });
        rows.sort(rowComparator(sortState.npc));
        dom.npcBody.innerHTML = rows.map((r) => r.html).join('');
        if (dom.npcCount) dom.npcCount.textContent = '· ' + st.byNpc.length + ' NPC types · ' + st.kills.toLocaleString('en-US') + ' kills';
        if (dom.npcEmpty) dom.npcEmpty.classList.toggle('hidden', rows.length > 0);
        updateSortInds(dom.npcTable, sortState.npc);
    }

    // ---------------------- By system ----------------------

    function sysRowHtml(r) {
        let name;
        if (r.nameDisp) {
            name = '<div class="system-cell">' +
                (r.sec != null ? '<span class="sec-pill ' + T.secClass(r.sec) + '">' + fmtSecVal(r.sec) + '</span>' : '') +
                esc(r.nameDisp) + '</div>';
        } else {
            name = '<div class="system-cell"><span class="sec-pill sec-unknown">?</span>Unknown system ' +
                '<button class="mini-btn assign" data-sys-fix="1">Set</button></div>';
        }
        let essCell = '<span style="color:var(--text-muted);">—</span>';
        if (r.nameDisp) {
            const label = (r.ess > 0 ? r.ess : 0) + '%' + (r.override !== undefined ? ' *' : '');
            essCell = '<span class="mini-btn" data-ess-cycle="' + esc(r.nameDisp) + '" title="Click to override ESS for this system (Auto → 0% → 40% → Auto). Overrides apply in Auto mode. * = manual override">' + label + '</span>';
        }
        const rateStr = r.rate >= 0 ? T.fmtISK(r.rate) : '—';
        const rateTitle = r.rate >= 0
            ? 'ISK/hour from completed 20-minute bounty ticks'
            : 'Waiting for a complete 20-minute bounty tick';
        return '<tr>' +
            '<td>' + name + '</td>' +
            '<td>' + esc(r.region || '—') + '</td>' +
            '<td class="num">' + r.kills + '</td>' +
            '<td class="num">' + T.fmtISK(r.gross) + '</td>' +
            '<td class="num">' + T.fmtISK(r.net) + '</td>' +
            '<td class="num">' + essCell + '</td>' +
            '<td class="num">' + T.fmtISK(r.bank) + '</td>' +
            '<td class="num" title="' + rateTitle + '">' + rateStr + '</td>' +
            '</tr>';
    }

    function renderSysTable(view) {
        if (!dom.sysBody) return;
        const st = view.stats;
        const rows = st.bySystem.map((sy) => {
            const info = sy.name ? indexes.systems.get(sy.name.toLowerCase()) : null;
            const rate = sy.tickRate;
            return {
                name: sy.name ? sy.name.toLowerCase() : '\uffff',
                region: info ? info.region : '',
                kills: sy.kills,
                gross: sy.gross,
                net: sy.net,
                ess: sy.essRate,
                bank: sy.bank,
                rate: rate == null ? -1 : rate,
                nameDisp: sy.name,
                sec: info ? info.sec : null,
                override: sy.name ? settings.essOverrides[sy.name.toLowerCase()] : undefined,
            };
        });
        rows.sort(rowComparator(sortState.sys));
        dom.sysBody.innerHTML = rows.map((r) => sysRowHtml(r)).join('');
        if (dom.sysCount) dom.sysCount.textContent = '· ' + st.bySystem.length + ' systems';
        if (dom.sysEmpty) dom.sysEmpty.classList.toggle('hidden', rows.length > 0);
        updateSortInds(dom.sysTable, sortState.sys);
    }

    // ---------------------- History ----------------------

    function histRowHtml(r) {
        const rateStr = r.rate >= 0 ? T.fmtISK(r.rate) : '—';
        const rateTitle = r.rate >= 0
            ? 'ISK/hour from completed 20-minute bounty ticks'
            : 'Waiting for a complete 20-minute bounty tick';
        return '<tr' + (r.id === activeViewId ? ' style="box-shadow: inset 2px 0 0 var(--accent);"' : '') + '>' +
            '<td class="mono">' + fmtDate(r.date) + (r.live ? ' <span class="chip ok">live</span>' : '') + '</td>' +
            '<td>' + esc(r.char) + '</td>' +
            '<td style="max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + esc(r.file) + '">' + esc(r.file) + '</td>' +
            '<td class="num">' + T.fmtDuration(r.dur) + '</td>' +
            '<td class="num">' + r.kills.toLocaleString('en-US') + '</td>' +
            '<td class="num">' + T.fmtISK(r.net) + '</td>' +
            '<td class="num" title="' + rateTitle + '">' + rateStr + '</td>' +
            '<td style="white-space:nowrap;"><button class="mini-btn" data-view-id="' + esc(r.id) + '">View</button> ' +
            '<button class="mini-btn" data-del-id="' + esc(r.id) + '" title="Delete this session" style="color:var(--danger);"><i class="fas fa-trash-can"></i></button></td>' +
            '</tr>';
    }

    function renderHistory() {
        if (!dom.histBody) return;
        if (!sessions.length) {
            dom.histBody.innerHTML = '';
            if (dom.histEmpty) dom.histEmpty.classList.remove('hidden');
            return;
        }
        if (dom.histEmpty) dom.histEmpty.classList.add('hidden');
        const rows = sortedSessions().map((s) => {
            const st = sessionStats(s);
            const rate = st.iskPerHour;
            return {
                date: s.start || s.updated || 0,
                char: s.char || '',
                file: s.file || '',
                dur: st.spanMs,
                kills: st.kills,
                net: st.net,
                rate: rate == null ? -1 : rate,
                id: s.id,
                live: !!s.live,
            };
        });
        rows.sort(rowComparator(sortState.hist));
        dom.histBody.innerHTML = rows.map((r) => histRowHtml(r)).join('');
        updateSortInds(dom.histTable, sortState.hist);
    }

    function renderAllTime() {
        const all = computeAllStats();
        if (dom.atKills) dom.atKills.textContent = all.kills.toLocaleString('en-US');
        if (dom.atNet) dom.atNet.textContent = fmtISKcard(all.net);
        if (dom.atTime) dom.atTime.textContent = T.fmtDuration(all.spanMs);
        if (dom.atSessions) dom.atSessions.textContent = String(sessions.length);
    }

    // ---------------------- Sorting ----------------------

    function rowComparator(state) {
        const key = state.key;
        const dir = state.dir;
        return (a, b) => {
            const va = a[key];
            const vb = b[key];
            if (typeof va === 'string' || typeof vb === 'string') {
                return String(va || '').localeCompare(String(vb || '')) * dir;
            }
            return ((va || 0) - (vb || 0)) * dir;
        };
    }

    function updateSortInds(tableEl, state) {
        if (!tableEl) return;
        tableEl.querySelectorAll('th[data-sort]').forEach((th) => {
            th.classList.remove('sort-asc', 'sort-desc');
            const icon = th.querySelector('.sort-ind');
            if (!icon) return;
            icon.className = 'fas fa-sort sort-ind';
            if (th.getAttribute('data-sort') === state.key) {
                th.classList.add(state.dir > 0 ? 'sort-asc' : 'sort-desc');
                icon.className = 'fas ' + (state.dir > 0 ? 'fa-sort-up' : 'fa-sort-down') + ' sort-ind';
            }
        });
    }

    function bindSorting(tableEl, tableKey, rerender) {
        if (!tableEl) return;
        tableEl.querySelectorAll('th[data-sort]').forEach((th) => {
            th.addEventListener('click', () => {
                const key = th.getAttribute('data-sort');
                const st = sortState[tableKey];
                if (st.key === key) st.dir = -st.dir;
                else { st.key = key; st.dir = NUMERIC_SORT[tableKey].has(key) ? -1 : 1; }
                rerender();
            });
        });
    }

    // ------------------------------------------------------------------
    // Assign popover (one-click NPC correction)
    // ------------------------------------------------------------------

    function closePopover() {
        if (popover && popover.parentNode) popover.parentNode.removeChild(popover);
        popover = null;
    }

    function openAssignPopover(anchorEl, session, ev) {
        closePopover();
        if (!session || !ev) { toast('Could not locate that kill row', 'error'); return; }
        const res = T.resolveEvent(ev, indexes, { useContext: !!settings.useContext });
        const totalSame = session.events.filter((e) => e.a === ev.a).length;
        popover = document.createElement('div');
        popover.className = 'popover';
        popover.innerHTML =
            '<input type="text" class="pop-search" spellcheck="false" placeholder="Search ' + indexes.rats.length.toLocaleString('en-US') + ' NPC types…">' +
            '<div style="font-size:11px;color:var(--text-muted);margin:0 2px 6px;line-height:1.4;">' +
            'Kill at ' + T.fmtClock(ev.t) + ' EVE · ' + T.fmtISK(ev.a) + ' ISK<br>' +
            (ev.ev && ev.ev.length ? 'recent NPCs: ' + esc(ev.ev.slice(0, 3).join(', ')) : 'no combat context logged') +
            '</div>' +
            '<div class="suggestions"></div>' +
            '<label class="apply-all"><input type="checkbox" class="pop-apply-all"> Apply to all ' + totalSame +
            ' kills at ' + T.fmtISK(ev.a) + ' ISK in this session</label>' +
            '<div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;">' +
            '<button class="mini-btn pop-reset">Reset this kill</button>' +
            (session.amountOverrides && session.amountOverrides[ev.a] != null
                ? '<button class="mini-btn pop-reset-all" style="color:var(--danger);">Remove fix for all ' + T.fmtISK(ev.a) + ' ISK</button>'
                : '') +
            '</div>';
        document.body.appendChild(popover);
        popover.style.position = 'fixed';
        const rect = anchorEl.getBoundingClientRect();
        const pw = popover.offsetWidth, ph = popover.offsetHeight;
        popover.style.left = Math.max(12, Math.min(window.innerWidth - pw - 12, rect.right - pw)) + 'px';
        let top = rect.bottom + 6;
        if (top + ph > window.innerHeight - 12) top = Math.max(12, rect.top - ph - 6);
        popover.style.top = top + 'px';

        const input = popover.querySelector('.pop-search');
        const wrap = popover.querySelector('.suggestions');
        const applyAll = popover.querySelector('.pop-apply-all');

        function sugItem(ix, tag) {
            const r = indexes.rats[ix];
            const sub = (T.ratGroup(indexes, ix) || T.ratFaction(indexes, ix)) + ' · ' + T.fmtISK(Math.round(r[2])) + ' ISK' + (tag ? ' · ' + tag : '');
            return '<div class="sug' + (tag === 'candidate' ? ' candidate' : '') + '" data-idx="' + ix + '">' +
                '<span class="sug-name">' + esc(r[1]) + '</span><span class="sug-sub">' + esc(sub) + '</span></div>';
        }

        function renderSugs(query) {
            let html = '';
            if (!query) {
                const seen = new Set();
                const seenNames = new Set();
                (res.candidates || []).slice(0, 8).forEach((ix) => {
                    const nm = indexes.rats[ix][1];
                    if (!seen.has(ix) && !seenNames.has(nm)) { seen.add(ix); seenNames.add(nm); html += sugItem(ix, 'candidate'); }
                });
                (ev.ev || []).forEach((n) => {
                    const ix = indexes.ratByName.get(n.toLowerCase());
                    if (ix == null) return;
                    const nm = indexes.rats[ix][1];
                    if (!seen.has(ix) && !seenNames.has(nm)) { seen.add(ix); seenNames.add(nm); html += sugItem(ix, 'fought'); }
                });
                if (!html) html = '<div class="sug"><span class="sug-sub">No bounty match — type the NPC name above.</span></div>';
            } else {
                const q = query.toLowerCase();
                let count = 0;
                for (let i = 0; i < indexes.rats.length && count < 25; i++) {
                    if (RAT_NAMES_LC[i].indexOf(q) !== -1) { html += sugItem(i, ''); count++; }
                }
                if (!html) html = '<div class="sug"><span class="sug-sub">No NPC matches "' + esc(query) + '"</span></div>';
            }
            wrap.innerHTML = html;
        }

        wrap.addEventListener('click', (e) => {
            const sugEl = e.target.closest('.sug[data-idx]');
            if (!sugEl) return;
            const ix = +sugEl.getAttribute('data-idx');
            const typeId = indexes.rats[ix][0];
            const all = !!(applyAll && applyAll.checked);
            closePopover();
            assignNpc(session, ev, typeId, all);
        });
        input.addEventListener('input', () => renderSugs(input.value.trim()));
        popover.querySelector('.pop-reset').addEventListener('click', () => { closePopover(); resetEventFix(session, ev); });
        const resetAll = popover.querySelector('.pop-reset-all');
        if (resetAll) resetAll.addEventListener('click', () => { closePopover(); resetAmountFix(session, ev.a); });
        renderSugs('');
        input.focus();
    }

    // ------------------------------------------------------------------
    // Exports & session maintenance
    // ------------------------------------------------------------------

    function buildCsv(view) {
        const ess = view.stats.essSettings || trackerEss();
        const rows = [[
            'time_eve', 'character', 'system', 'npc', 'faction', 'group', 'gross_isk', 'ess_pct',
            'net_after_ess', 'tax_pct', 'net_isk', 'net_incl_bank', 'confidence', 'payment_adjusted',
        ]];
        const events = view.events.slice().sort((a, b) => a.t - b.t);
        for (const ev of events) {
            const r = T.resolveEvent(ev, indexes, { useContext: !!settings.useContext });
            const essInfo = T.essRateFor(ev.sys, ess, indexes.systems);
            const taxF = 1 - ess.taxPct / 100;
            const afterEss = (ev.a * (1 - essInfo.rate / 100)) * taxF;
            const bank = ev.a * (essInfo.rate / 100) * taxF;
            const conf = r.status === 'm' ? 'manual' : r.status === 'r' ? 'resolved' : r.status === 'g' ? 'guess' : 'unmatched';
            rows.push([
                new Date(ev.t).toISOString().replace('T', ' ').slice(0, 19),
                ev.ch || '',
                ev.sys || '',
                r.idx != null ? indexes.rats[r.idx][1] : '',
                r.idx != null ? T.ratFaction(indexes, r.idx) : '',
                r.idx != null ? T.ratGroup(indexes, r.idx) : '',
                ev.a,
                essInfo.rate,
                Math.round(afterEss),
                ess.taxPct,
                Math.round(afterEss + (ess.includesBank ? bank : 0)),
                Math.round(afterEss + bank),
                conf,
                ev.adj ? 'yes' : '',
            ]);
        }
        return rows.map((r) => r.map(csvField).join(',')).join('\r\n');
    }

    function exportCsv() {
        const view = currentView || getActiveView();
        if (!view.events.length) { toast('Nothing to export yet', 'error'); return; }
        const csv = buildCsv(view);
        const stamp = new Date().toISOString().slice(0, 10);
        const base = view.session ? (view.session.file || 'session').replace(/\.[^.]*$/, '') : ('all-sessions-' + stamp);
        download('npc-kills-' + base + '.csv', '\ufeff' + csv, 'text/csv;charset=utf-8');
        toast('Exported ' + view.events.length.toLocaleString('en-US') + ' kill rows to CSV', 'success');
    }

    function exportJson() {
        flushSaves();
        const payload = {
            app: 'Rusty NPC Tracker',
            exported: new Date().toISOString(),
            sde: DATA.sde,
            settings: settings,
            sessions: sessions,
        };
        download('rusty-npc-tracker-' + new Date().toISOString().slice(0, 10) + '.json', JSON.stringify(payload), 'application/json');
        toast('Exported ' + sessions.length + ' session(s) to JSON', 'success');
    }

    async function deleteSession(id) {
        const s = sessionsById[id];
        if (!s) return;
        if (!window.confirm('Delete session "' + (s.file || s.id) + '" (' + s.events.length + ' kills)?')) return;
        suppressFile(s.file);
        watched = watched.filter((w) => w.sessionId !== id);
        sessions = sessions.filter((x) => x.id !== id);
        delete sessionsById[id];
        if (activeViewId === id) activeViewId = 'all';
        selectSig = '';
        try { await idbDelete('sessions', id); } catch (e) { /* ignore */ }
        invalidateAllStats();
        scheduleRender(true);
        toast('Session deleted', '', 2500);
    }

    async function clearAll() {
        if (!sessions.length) return;
        if (!window.confirm('Delete all ' + sessions.length + ' stored session(s)? This cannot be undone.')) return;
        watched.forEach((w) => suppressFile(w.name));
        sessions = [];
        sessionsById = Object.create(null);
        activeViewId = 'all';
        lastLiveId = null;
        selectSig = '';
        try { await idbClear('sessions'); } catch (e) { /* ignore */ }
        invalidateAllStats();
        scheduleRender(true);
        toast('All sessions cleared', '', 3000);
    }

    function cycleEss(systemName) {
        if (!systemName) return;
        const key = systemName.toLowerCase();
        const cur = settings.essOverrides[key];
        if (cur === undefined) settings.essOverrides[key] = 0;
        else if (cur === 0) settings.essOverrides[key] = 40;
        else delete settings.essOverrides[key];
        onSettingsChanged();
        const now = settings.essOverrides[key];
        toast('ESS for ' + systemName + ': ' + (now !== undefined ? now + '% (manual override)' : 'automatic (by security status)'), '', 2600);
    }

    function setSystemForUnknown(view, systemName) {
        const info = indexes.systems.get(systemName.toLowerCase());
        if (!info) { toast('Unknown solar system: ' + systemName, 'error'); return; }
        let n = 0;
        const list = view.session ? [view.session] : sessions;
        for (const s of list) {
            let touched = false;
            for (const ev of s.events) {
                if (!ev.sys) { ev.sys = info.name; n++; touched = true; }
            }
            if (touched) { saveSessionSoon(s); }
        }
        invalidateAllStats();
        scheduleRender(true);
        toast('Set ' + n + ' kill(s) to ' + info.name, 'success');
    }

    // ------------------------------------------------------------------
    // Settings UI
    // ------------------------------------------------------------------

    let settingsSaveTimer = null;

    function syncSettingsUI() {
        if (dom.essMode) dom.essMode.value = settings.essMode;
        if (dom.essCustom) { dom.essCustom.value = settings.essCustom; dom.essCustom.disabled = settings.essMode !== 'custom'; }
        if (dom.essNull) dom.essNull.value = settings.essNull;
        if (dom.taxPct) dom.taxPct.value = settings.taxPct;
        if (dom.incBank) dom.incBank.checked = !!settings.incBank;
        if (dom.useContext) dom.useContext.checked = !!settings.useContext;
    }

    function saveSettingsSoon() {
        clearTimeout(settingsSaveTimer);
        settingsSaveTimer = setTimeout(() => { idbPut('kv', settings, 'settings').catch(() => {}); }, 400);
    }

    function onSettingsChanged() {
        invalidateAllStats();
        sessions.forEach((s) => { s._stats = null; s._statsKey = ''; });
        saveSettingsSoon();
        scheduleRender(true);
    }

    function numVal(input, fallback) {
        const v = parseFloat(input && input.value);
        if (isNaN(v)) return fallback;
        return Math.max(0, Math.min(100, v));
    }

    function bindSettings() {
        if (dom.essMode) dom.essMode.addEventListener('change', () => {
            settings.essMode = dom.essMode.value;
            syncSettingsUI();
            onSettingsChanged();
        });
        if (dom.essCustom) dom.essCustom.addEventListener('input', () => {
            settings.essCustom = numVal(dom.essCustom, 40);
            onSettingsChanged();
        });
        if (dom.essNull) dom.essNull.addEventListener('input', () => {
            settings.essNull = numVal(dom.essNull, 40);
            onSettingsChanged();
        });
        if (dom.taxPct) dom.taxPct.addEventListener('input', () => {
            settings.taxPct = numVal(dom.taxPct, 0);
            onSettingsChanged();
        });
        if (dom.incBank) dom.incBank.addEventListener('change', () => {
            settings.incBank = dom.incBank.checked;
            onSettingsChanged();
        });
        if (dom.useContext) dom.useContext.addEventListener('change', () => {
            settings.useContext = dom.useContext.checked;
            onSettingsChanged();
        });
    }

    // ------------------------------------------------------------------
    // Event wiring
    // ------------------------------------------------------------------

    function bindEvents() {
        if (dom.connectBtn) dom.connectBtn.addEventListener('click', connectFolder);
        if (dom.reconnectBtn) {
            dom.reconnectBtn.addEventListener('click', async () => {
                if (!dirHandle) return;
                try {
                    let perm = 'prompt';
                    if (dirHandle.queryPermission) perm = await dirHandle.queryPermission({ mode: 'read' });
                    if (perm !== 'granted' && dirHandle.requestPermission) perm = await dirHandle.requestPermission({ mode: 'read' });
                    if (perm !== 'granted') { toast('Permission for "' + dirHandle.name + '" was denied', 'error'); return; }
                } catch (err) {
                    toast('Could not re-open the folder — connect it again.', 'error');
                    return;
                }
                const resolved = await resolveGamelogsDir(dirHandle);
                if (resolved.found) {
                    dirHandle = resolved.handle;
                    try { await idbPut('kv', dirHandle, 'gamelogsDir'); } catch (err) { /* non-fatal */ }
                }
                hideReconnect();
                dom.connectBtn.classList.add('hidden');
                userPaused = false;
                followLiveSession = true;
                await startWatching();
            });
        }
        if (dom.pauseBtn) dom.pauseBtn.addEventListener('click', () => setUserPaused(!userPaused));
        if (dom.esiLinkBtn) dom.esiLinkBtn.addEventListener('click', linkEsi);
        if (dom.esiUnlinkBtn) dom.esiUnlinkBtn.addEventListener('click', unlinkEsi);
        if (dom.resetLayoutBtn) dom.resetLayoutBtn.addEventListener('click', () => {
            try { localStorage.removeItem(LAYOUT_KEY); } catch (e) { /* ignore */ }
            location.reload();
        });
        if (dom.fileInput) dom.fileInput.addEventListener('change', () => {
            handleFiles(dom.fileInput.files);
            dom.fileInput.value = '';
        });
        if (dom.pasteBtn) dom.pasteBtn.addEventListener('click', handlePaste);
        if (dom.dropZone) {
            dom.dropZone.addEventListener('click', () => dom.fileInput.click());
            ['dragenter', 'dragover'].forEach((ev) => dom.dropZone.addEventListener(ev, (e) => {
                e.preventDefault();
                dom.dropZone.classList.add('dragover');
            }));
            ['dragleave', 'drop'].forEach((ev) => dom.dropZone.addEventListener(ev, () => dom.dropZone.classList.remove('dragover')));
            dom.dropZone.addEventListener('drop', (e) => {
                e.preventDefault();
                if (e.dataTransfer && e.dataTransfer.files) handleFiles(e.dataTransfer.files);
            });
        }
        window.addEventListener('dragover', (e) => e.preventDefault());
        window.addEventListener('drop', (e) => e.preventDefault());

        if (dom.sessionSelect) dom.sessionSelect.addEventListener('change', () => {
            activeViewId = dom.sessionSelect.value;
            scheduleRender(true);
        });

        if (dom.feedBody) dom.feedBody.addEventListener('click', (e) => {
            const btn = e.target.closest('[data-feed-i]');
            if (!btn) return;
            const fr = currentFeedRows[+btn.getAttribute('data-feed-i')];
            if (!fr) return;
            const assignIdx = btn.getAttribute('data-assign-idx');
            if (assignIdx != null) {
                assignNpc(fr.session, fr.ev, indexes.rats[+assignIdx][0], false);
            } else {
                openAssignPopover(btn, fr.session, fr.ev);
            }
        });

        if (dom.npcBody) dom.npcBody.addEventListener('click', (e) => {
            const btn = e.target.closest('[data-npc-fix]');
            if (!btn) return;
            const n = currentNpcFixRefs[+btn.getAttribute('data-npc-fix')];
            if (!n) return;
            const view = currentView || getActiveView();
            const ev = findSampleEvent(view, n);
            if (!ev) { toast('Could not locate a matching kill row', 'error'); return; }
            const session = view.session || (view.stats._eventSession && view.stats._eventSession.get(ev));
            openAssignPopover(btn, session, ev);
        });

        if (dom.sysBody) dom.sysBody.addEventListener('click', (e) => {
            const essBtn = e.target.closest('[data-ess-cycle]');
            if (essBtn) { cycleEss(essBtn.getAttribute('data-ess-cycle')); return; }
            const fixBtn = e.target.closest('[data-sys-fix]');
            if (fixBtn) {
                const view = currentView || getActiveView();
                const name = window.prompt('Which solar system were these kills in? (e.g. R-ARKN)');
                if (name && name.trim()) setSystemForUnknown(view, name.trim());
            }
        });

        if (dom.histBody) dom.histBody.addEventListener('click', (e) => {
            const v = e.target.closest('[data-view-id]');
            if (v) { activeViewId = v.getAttribute('data-view-id'); scheduleRender(true); return; }
            const d = e.target.closest('[data-del-id]');
            if (d) deleteSession(d.getAttribute('data-del-id'));
        });

        if (dom.btnImportRecent) dom.btnImportRecent.addEventListener('click', importRecentLogs);
        if (dom.btnExportCsv) dom.btnExportCsv.addEventListener('click', exportCsv);
        if (dom.btnExportJson) dom.btnExportJson.addEventListener('click', exportJson);
        if (dom.btnClearAll) dom.btnClearAll.addEventListener('click', clearAll);

        bindSorting(dom.npcTable, 'npc', () => { renderNpcTable(currentView || getActiveView()); });
        bindSorting(dom.sysTable, 'sys', () => { renderSysTable(currentView || getActiveView()); });
        bindSorting(dom.histTable, 'hist', renderHistory);

        document.addEventListener('visibilitychange', () => {
            if (document.hidden) {
                flushSaves();
                stopPolling();
                stopEsiPolling();
            } else {
                if (dirHandle && !userPaused) { startPolling(); pollOnce(); }
                if (esiCharacter()) startEsiPolling();
            }
        });
        window.addEventListener('pagehide', flushSaves);
        document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closePopover(); });
        document.addEventListener('mousedown', (e) => {
            if (!popover) return;
            if (popover.contains(e.target)) return;
            if (e.target.closest && e.target.closest('.mini-btn.assign')) return;
            closePopover();
        });
    }

    function startClock() {
        const tick = () => {
            if (!dom.eveClock) return;
            const d = new Date();
            dom.eveClock.textContent = pad2(d.getUTCHours()) + ':' + pad2(d.getUTCMinutes()) + ':' + pad2(d.getUTCSeconds());
        };
        tick();
        setInterval(tick, 1000);
        // DPS is time-windowed: refresh the summary cards once a second while a
        // live session is active so they decay between log writes.
        setInterval(() => {
            if (!currentView) return;
            const live = currentView.session
                ? currentView.session.live
                : sessions.some((s) => s.live);
            if (!live) return;
            currentView = getActiveView();
            renderSummary(currentView);
        }, 1000);
    }

    // ------------------------------------------------------------------
    // Boot
    // ------------------------------------------------------------------

    async function boot() {
        bindEvents();
        bindSettings();
        startClock();
        syncSettingsUI();
        updateLiveUI();
        try {
            const savedSuppressed = await idbGet('kv', 'suppressed');
            if (savedSuppressed) suppressedFiles = savedSuppressed;
            const savedSettings = await idbGet('kv', 'settings');
            if (savedSettings) {
                settings = Object.assign({}, SETTINGS_DEFAULTS, savedSettings, { essOverrides: savedSettings.essOverrides || {} });
            }
            const savedSessions = await idbGetAll('sessions');
            sessions = (savedSessions || []).map((s) => ({
                id: s.id,
                file: s.file,
                char: s.char,
                start: s.start || null,
                end: s.end || 0,
                updated: s.updated || 0,
                source: s.source || 'file',
                live: false,
                events: s.events || [],
                damage: s.damage || [],
                misses: s.misses || [],
                logEnd: s.logEnd || 0,
                amountOverrides: s.amountOverrides || {},
                eventFixes: s.eventFixes || {},
            }));
            sessionsById = Object.create(null);
            sessions.forEach((s) => { sessionsById[s.id] = s; });
            syncSettingsUI();
            const newest = sortedSessions()[0];
            activeViewId = newest ? newest.id : 'all';
            if (sessions.length) {
                setStatus(sessions.length + ' stored session(s) loaded — connect the Gamelogs folder for live tracking, or drop old logs in.');
            }
        } catch (err) {
            console.warn('local storage unavailable:', err);
        }
        updateEsiUI();
        if (esiCharacter()) startEsiPolling();
        scheduleRender(true);

        try {
            const handle = await idbGet('kv', 'gamelogsDir');
            if (handle) {
                dirHandle = handle;
                let perm = 'prompt';
                try { if (handle.queryPermission) perm = await handle.queryPermission({ mode: 'read' }); } catch (e) { /* ignore */ }
                if (perm === 'granted') {
                    dom.connectBtn.classList.add('hidden');
                    dom.pauseBtn.classList.remove('hidden');
                    followLiveSession = true;
                    await startWatching();
                } else {
                    showReconnect(handle.name);
                }
            }
        } catch (err) { /* ignore */ }
    }

    loadLayout();
    setupLayout();
    boot();
})();
